{"path": "dominoes.py", "content": "def can_chain(dominoes):
    """Return a list of (a, b) tuples forming a closed domino chain, or None."""
    stones = [tuple(d) for d in dominoes]
    if not stones:
        return []

    used = [False] * len(stones)
    chain = [stones[0]]
    used[0] = True

    def search():
        if len(chain) == len(stones):
            return chain[0][0] == chain[-1][1]
        end = chain[-1][1]
        tried = set()
        for i, (a, b) in enumerate(stones):
            if used[i]:
                continue
            for stone in ((a, b), (b, a)):
                if stone[0] != end or stone in tried:
                    continue
                tried.add(stone)
                used[i] = True
                chain.append(stone)
                if search():
                    return True
                chain.pop()
                used[i] = False
        return False

    return list(chain) if search() else None
